window.DEX_DATA["sources:backport-0c75e2b0d7c342b4"]={"json":{"skins":[{"filename":"rancher.png"}],"names":[{"name":"比利·鲍勃"},{"name":"牛仔罗伊"},{"name":"小巴巴·皮特"},{"name":"老克莱图斯"},{"name":"泽布"}],"chat":[{"lines":[{"text":"孩子，大奶罐可有一千种用处呢。"},{"text":"所以才需要我们这些牧场主，不然你们的牛奶和皮革从哪儿来？"}]},{"lines":[{"text":"城里人是不是都喜欢晒成小麦色啊？"},{"text":"小伙子，来牧场跟我干活吧，保证让你晒出颜色！"}]},{"lines":[{"text":"当牧场主真辛苦，我的背都快累坏了。"},{"text":"我只想在摇椅上坐几个小时，好好歇歇。"}]},{"lines":[{"text":"有空该来乡下看看。"},{"text":"呼吸点清新的乡间空气。"}]}]}};
